#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# npm run knock:setup walks a person through the Knock settings that can't be
# kept as code in knock/ (ADR 0016). Run it once per Knock environment and once
# per fork: Development first, then Production as step 1 of going live.

# The channel keys the knock/ workflows send through. Change one only together
# with every matching channel_key in knock/workflows/*/workflow.json.
IN_APP_CHANNEL_KEY="knock-in-app" # the in-app feed channel Knock creates
EMAIL_CHANNEL_KEY="postmark"      # the email channel stage 3 creates

RESPONSE_FILTER='{"actor": {"only": ["id", "name"]}}'
PAYLOAD_OVERRIDE='{"MessageStream": "notifications"}'
FROM_EMAIL="hello@cadence.dev"
FROM_NAME="Cadence"
POSTMARK_STREAM="notifications"
SERVICE_TOKEN_PREFIX="knock_st_"
COURSE_REPO="ai-hero-dev/cohort-005-project"

KNOCK_HOME="https://dashboard.knock.app"
KNOCK="$KNOCK_HOME/~"
POSTMARK_SERVERS="https://account.postmarkapp.com/servers"

ORIGIN_REPO=""
KNOCK_ENV=""
_SEEN_IN_APP_KEY=""
CURRENT_STAGE=""
DONE_NOW=()    # stages finished this run
DONE_BEFORE=() # stages the person said were already done

die() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }

lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }

# begin "Title" starts a stage and remembers its title for the summary.
begin() { CURRENT_STAGE="$1"; stage "$1"; }

# skip_if_done "condition" says how to tell the stage is already done, and lets
# the person skip it. Succeeds when they skip.
skip_if_done() {
  printf '\n'
  say "${BOLD}Already done if:${RESET}"
  say "  $1"
  if confirm "Is it already done? Skip this stage"; then
    DONE_BEFORE+=("$CURRENT_STAGE")
    return 0
  fi
  printf '\n'
  return 1
}

# verify "question" has the person check the result. A "no" can be fixed and
# checked again, or left on the summary's to-do list.
verify() {
  printf '\n'
  while ! confirm "$1"; do
    if ! confirm "Fix it and check again? (No leaves it on the to-do list)"; then
      SKIPPED+=("$CURRENT_STAGE: not finished. Re-run npm run knock:setup to finish it")
      return 0
    fi
  done
  DONE_NOW+=("$CURRENT_STAGE")
  printf '  %s✓ done%s\n' "$GREEN" "$RESET"
}

# origin_repo prints the owner/repo of the origin remote on GitHub.
origin_repo() {
  local url re='github\.com[:/]([^/]+)/([^/]+)$'
  url=$(git remote get-url origin 2>/dev/null) || return 1
  url=${url%/}
  url=${url%.git}
  [[ "$url" =~ $re ]] || return 1
  printf '%s/%s' "${BASH_REMATCH[1]}" "${BASH_REMATCH[2]}"
}

choose_environment() {
  local reply=""
  _clear
  printf '\n%s%s  Knock setup%s\n\n' "$BOLD" "$BLUE" "$RESET"
  say "Which Knock environment are you setting up?"
  say "  1) Development   run it first, once per fork"
  say "  2) Production    step 1 of going live"
  while :; do
    printf '  %s? Choose 1 or 2:%s ' "$YELLOW" "$RESET"
    read -r reply || die "No environment chosen."
    case "$(lower "$reply")" in
      1 | d | dev | development) KNOCK_ENV=development; return 0 ;;
      2 | p | prod | production) KNOCK_ENV=production; return 0 ;;
    esac
    warn "Type 1 for Development or 2 for Production."
  done
}

# ── Clipboard ─────────────────────────────────────────────────────────────
# A long value pasted at a terminal prompt is cut off without warning (#22),
# so secrets are read from the clipboard instead.

_has_clipboard() {
  command -v pbpaste >/dev/null 2>&1 || command -v wl-paste >/dev/null 2>&1 ||
    command -v xclip >/dev/null 2>&1 || command -v xsel >/dev/null 2>&1 ||
    command -v powershell.exe >/dev/null 2>&1
}

_paste() {
  if   command -v pbpaste  >/dev/null 2>&1; then pbpaste
  elif command -v wl-paste >/dev/null 2>&1; then wl-paste --no-newline
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard -o
  elif command -v xsel     >/dev/null 2>&1; then xsel --clipboard --output
  elif command -v powershell.exe >/dev/null 2>&1; then powershell.exe -NoProfile -Command Get-Clipboard
  else return 1; fi
}

_copy() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v xsel     >/dev/null 2>&1; then printf '%s' "$1" | xsel --clipboard --input
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# copy_text "text" puts a value that isn't secret on the clipboard, so the
# person pastes it rather than retyping JSON.
copy_text() {
  if _copy "$1" 2>/dev/null; then note "(it's on your clipboard)"; fi
}

# read_clipboard KEY "label" PREFIX reads a secret that starts with PREFIX into
# $KEY. It never prints the value, only its length, and clears the clipboard
# once it's read. Without a clipboard command it falls back to hidden input.
_TYPED_SECRET=""
read_clipboard() {
  local key="$1" label="$2" prefix="$3" value="" clipboard=no
  if _has_clipboard; then clipboard=yes; fi
  while :; do
    if [[ "$clipboard" == yes ]]; then
      pause "Copy the $label, then press Enter. The wizard reads it from your clipboard."
      if ! value=$(_paste 2>/dev/null); then
        warn "Couldn't read your clipboard."
        clipboard=no
        continue
      fi
    else
      warn "No clipboard to read, so paste it here. A long paste can be cut off."
      ask_secret _TYPED_SECRET "Paste the $label (input hidden):" || true
      value="$_TYPED_SECRET"
    fi
    value=${value//[[:space:]]/}
    [[ "$value" == "$prefix"?* ]] && break
    warn "That isn't a $label: it should start with $prefix."
    confirm "Copy it again and retry?" || return 1
  done
  if [[ "$clipboard" == yes ]]; then
    _copy "" 2>/dev/null || true
    note "read a ${#value}-character $label, and cleared the clipboard"
  else
    note "read a ${#value}-character $label"
  fi
  printf -v "$key" '%s' "$value"
}

# ── GitHub ────────────────────────────────────────────────────────────────
# Secrets go to the origin repo, never the course repo. gh alone can't be
# trusted to pick origin: it prefers a remote named upstream.

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# secret_on_github NAME prints yes, no, or why it can't tell.
secret_on_github() {
  local names=""
  if ! _gh_ready; then printf 'unknown (gh is missing or logged out)'; return 0; fi
  if ! names=$(gh secret list -R "$ORIGIN_REPO" --json name --jq '.[].name' 2>/dev/null); then
    printf 'unknown (gh secret list failed)'
    return 0
  fi
  if printf '%s\n' "$names" | grep -qx "$1"; then printf 'yes'; else printf 'no'; fi
}

# set_origin_secret NAME VALUE sets an Actions secret on the origin repo. The
# value goes in on stdin, so it never shows in a process list.
set_origin_secret() {
  local name="$1" value="$2" err=""
  if _gh_ready && err=$(printf '%s' "$value" | gh secret set "$name" -R "$ORIGIN_REPO" 2>&1 >/dev/null); then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s on %s\n' "$GREEN" "$RESET" "$name" "$ORIGIN_REPO"
    return 0
  fi
  SKIPPED+=("GitHub secret $name: run gh secret set $name -R $ORIGIN_REPO and paste the token")
  warn "couldn't set GitHub secret $name on $ORIGIN_REPO${err:+: $err}"
  return 1
}

# ── Stages ────────────────────────────────────────────────────────────────

stage_environments() {
  begin "Turn on environments"
  say "A new Knock account has only Production. Turning on environments adds"
  say "Development, where every branch's drafts go. It's account-wide and can't"
  say "be undone. Cadence's own account did it in #22; a fork's new account needs it."
  skip_if_done "the environment picker at the top of the Knock dashboard offers Development and Production." && return 0
  open_url "$KNOCK/settings/environments"
  step "This is Settings → Version control → Environments. It needs the owner or admin role."
  step "Click Enable environments, then confirm."
  verify "Does the Environments page now list Development and Production?"
}

# stage_response_filter Development|Production
stage_response_filter() {
  local env="$1"
  begin "In-app response filter ($env)"
  say "Knock's feed sends each actor's whole user record, email included, to the"
  say "recipient's browser. This filter keeps only the actor's id and name (ADR 0015)."
  skip_if_done "the in-app feed channel's $env configuration has the API response filter $RESPONSE_FILTER." && return 0
  open_url "$KNOCK/settings/integrations/channels"
  step "This is Settings → Channels and sources. Open the in-app feed channel"
  say  "  that Knock created with the account."
  if ! confirm "Is that channel's key $IN_APP_CHANNEL_KEY? (It's shown on the channel's page)"; then
    warn "The knock/ workflows send their in-app steps to $IN_APP_CHANNEL_KEY."
    ask _SEEN_IN_APP_KEY "Type the key Knock shows:" || _SEEN_IN_APP_KEY="unknown"
    SKIPPED+=("In-app channel key is $_SEEN_IN_APP_KEY, not $IN_APP_CHANNEL_KEY: change IN_APP_CHANNEL_KEY in scripts/knock-setup.sh and every in-app channel_key in knock/workflows to match")
  fi
  step "Under Environment configurations, click $env, then open Advanced."
  step "Paste this into API response filter, then click Save changes:"
  say  "    $RESPONSE_FILTER"
  copy_text "$RESPONSE_FILTER"
  verify "Does $env's API response filter now read $RESPONSE_FILTER?"
}

stage_sandbox_channel() {
  begin "Postmark email channel in sandbox mode (Development)"
  say "Every email step sends through the email channel with key $EMAIL_CHANNEL_KEY."
  say "In Development it runs in sandbox mode: Knock renders each email in its"
  say "dashboard but never calls Postmark, needs no Postmark token, and isn't billed."
  skip_if_done "Channels and sources has a Postmark channel with key $EMAIL_CHANNEL_KEY whose Development configuration has Sandbox mode on." && return 0
  open_url "$KNOCK/settings/integrations/channels"
  step "If there's no Postmark channel with key $EMAIL_CHANNEL_KEY, create one:"
  say  "    type Email, provider Postmark, name Postmark, key $EMAIL_CHANNEL_KEY."
  warn "Check the key before you save: a channel's key can't be changed later."
  step "Open the channel. Under Environment configurations, click Development."
  step "Settings: From email address $FROM_EMAIL. API key can stay empty in sandbox mode."
  step "Overrides: From name $FROM_NAME. Leave Reply-to empty."
  step "Advanced: turn Sandbox mode on, then click Save changes."
  verify "Does the $EMAIL_CHANNEL_KEY channel's Development configuration show Sandbox mode on?"
}

stage_enhanced_security_off() {
  begin "Enhanced security stays off (Development)"
  say "With enhanced security off, Development also accepts feed reads without a"
  say "signed user token. Knock still checks any token that is sent, and Cadence"
  say "always sends one, so Development signs the same way Production does (#22)."
  skip_if_done "Platform → API keys, with Development picked at the top, shows Enhanced security mode off." && return 0
  open_url "$KNOCK_HOME"
  step "Pick Development in the environment picker at the top of the dashboard."
  step "Go to Platform → API keys (older dashboards: Developers → API keys)."
  step "If Enhanced security mode is on, turn it off. It's off by default."
  verify "Does Development's API keys page show Enhanced security mode off?"
}

stage_postmark_stream() {
  begin "Postmark: the notifications message stream"
  say "Notification emails go out on their own transactional stream, $POSTMARK_STREAM."
  say "Postmark keeps suppressions per stream, so a spam complaint about a"
  say "Notification can't stop that person's Receipts, which stay on outbound."
  skip_if_done "the Postmark server Cadence sends Receipts from has a Transactional message stream with ID $POSTMARK_STREAM." && return 0
  open_url "$POSTMARK_SERVERS"
  step "Open the server Cadence sends Receipts from (Production's POSTMARK_SERVER_TOKEN)."
  step "Open its Message Streams and create a new stream."
  step "Type: Transactional. Name: Notifications. ID: $POSTMARK_STREAM."
  warn "Check the ID before you create it: a stream's ID can't be changed later."
  verify "Does the server list a Transactional stream with ID $POSTMARK_STREAM?"
}

stage_postmark_channel() {
  begin "Postmark email channel (Production)"
  say "Production sends real email through Postmark, from $FROM_NAME <$FROM_EMAIL>,"
  say "on the $POSTMARK_STREAM stream. The Postmark token goes straight from"
  say "Postmark into Knock: this wizard never sees it."
  skip_if_done "the $EMAIL_CHANNEL_KEY channel's Production configuration has an API key, From email address $FROM_EMAIL, From name $FROM_NAME, no Reply-to, Payload overrides $PAYLOAD_OVERRIDE, and Sandbox mode off." && return 0
  open_url "$POSTMARK_SERVERS"
  step "Open the same Postmark server → API Tokens, and copy its Server API token."
