  step "Open the $EMAIL_CHANNEL_KEY channel (the Development run created it)."
  step "Under Environment configurations, click Production."
  step "Settings: paste the token into API key. From email address: $FROM_EMAIL."
  step "Advanced: make sure Sandbox mode is off."
  pause "Press Enter for the overrides. They replace what's on your clipboard."
  step "Overrides: From name $FROM_NAME. Leave Reply-to empty, so replies go to From."
  step "Paste this into Payload overrides, then click Save changes:"
  say  "    $PAYLOAD_OVERRIDE"
  copy_text "$PAYLOAD_OVERRIDE"
  verify "Does Production show an API key, From $FROM_EMAIL, From name $FROM_NAME, no Reply-to, that payload override, and Sandbox mode off?"
}

stage_enhanced_security_on() {
  begin "Enhanced security on (Production)"
  say "With enhanced security on, Knock rejects feed and preference calls that"
  say "come without a signed user token, so the public key can't act as any user."
  say "Cadence already signs a token for every request, so nothing in Cadence changes."
  skip_if_done "Platform → API keys, with Production picked at the top, shows Enhanced security mode on." && return 0
  open_url "$KNOCK_HOME"
  step "Pick Production in the environment picker at the top of the dashboard."
  step "Go to Platform → API keys (older dashboards: Developers → API keys)."
  step "Turn Enhanced security mode on."
  verify "Does Production's API keys page show Enhanced security mode on?"
}

stage_read_only() {
  begin "Production read-only"
  say "With \"Modify resources in any environment\" off, every environment except"
  say "Development is read-only, so only a promote from main changes Production"
  say "(ADR 0016)."
  skip_if_done "Settings → Permissions shows Modify resources in any environment off." && return 0
  open_url "$KNOCK/settings/permissions"
  step "This is Settings → Permissions. It needs the owner or admin role."
  step "Turn off Modify resources in any environment. It's on by default."
  verify "Is Modify resources in any environment now off?"
}

stage_service_token() {
  local in_env=no on_github="" token=""
  begin "Service token"
  say "npm run knock:push and the merge Action reach Knock with a service token."
  say "One token covers every environment and can't be scoped, so local scripts"
  say "only ever target Development. The Cadence server never holds it."
  if [[ -n "$(_existing KNOCK_SERVICE_TOKEN || true)" ]]; then in_env=yes; fi
  on_github=$(secret_on_github KNOCK_SERVICE_TOKEN)
  printf '\n'
  note "KNOCK_SERVICE_TOKEN in $ENV_FILE: $in_env"
  note "KNOCK_SERVICE_TOKEN in $ORIGIN_REPO's Actions secrets: $on_github"
  skip_if_done "both lines above say yes." && return 0

  if [[ "$in_env" == yes ]] && confirm "Use the token already in $ENV_FILE? (No creates a new one)"; then
    token=$(_existing KNOCK_SERVICE_TOKEN)
  else
    open_url "$KNOCK/settings/service-tokens"
    step "This is Settings → Service tokens. It needs the owner or admin role."
    step "Click + New token, name it $ORIGIN_REPO, and generate it."
    warn "Knock shows a service token only once, so copy it now."
    if ! read_clipboard token "Knock service token" "$SERVICE_TOKEN_PREFIX"; then
      SKIPPED+=("$CURRENT_STAGE: no token read. Re-run npm run knock:setup to finish it")
      return 0
    fi
    write_env KNOCK_SERVICE_TOKEN "$token"
  fi

  printf '\n'
  if ! confirm "Set KNOCK_SERVICE_TOKEN in the Actions secrets of $ORIGIN_REPO?"; then
    SKIPPED+=("GitHub secret KNOCK_SERVICE_TOKEN: run gh secret set KNOCK_SERVICE_TOKEN -R $ORIGIN_REPO and paste the token")
    return 0
  fi
  set_origin_secret KNOCK_SERVICE_TOKEN "$token" || return 0
  if [[ "$(secret_on_github KNOCK_SERVICE_TOKEN)" == yes ]]; then
    DONE_NOW+=("$CURRENT_STAGE")
    printf '  %s✓ done:%s gh secret list shows KNOCK_SERVICE_TOKEN on %s\n' "$GREEN" "$RESET" "$ORIGIN_REPO"
  else
    SKIPPED+=("GitHub secret KNOCK_SERVICE_TOKEN: gh secret list -R $ORIGIN_REPO doesn't show it yet")
  fi
}

# summary follows finish with what it doesn't show: the stages done this run,
# the ones that were already done, and what to do next.
summary() {
  local s
  if (( ${#DONE_NOW[@]} )); then
    note "Done this run:"
    for s in "${DONE_NOW[@]}"; do note "  - $s"; done
  fi
  if (( ${#DONE_BEFORE[@]} )); then
    note "Already done, so skipped:"
    for s in "${DONE_BEFORE[@]}"; do note "  - $s"; done
  fi
  printf '\n'
  if (( ${#SKIPPED[@]} )); then
    say "Re-run npm run knock:setup once the to-do list is done. Skip the stages that are."
  elif [[ "$KNOCK_ENV" == development ]]; then
    say "Next: npm run knock:push loads the knock/ workflows into Development."
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

local top=""
top=$(git rev-parse --show-toplevel 2>/dev/null) ||
  die "Run npm run knock:setup from inside your copy of the Cadence repo."
cd "$top"
ORIGIN_REPO=$(origin_repo) ||
  die "The origin remote isn't a GitHub repo, so there's nowhere to put KNOCK_SERVICE_TOKEN."
if [[ "$(lower "$ORIGIN_REPO")" == "$COURSE_REPO" ]]; then
  die "origin is the course repo ($COURSE_REPO). Run this from your own copy, whose origin is your fork."
fi

choose_environment

if [[ "$KNOCK_ENV" == development ]]; then
  TOTAL_STAGES=5
  banner "Knock setup · Development"
  stage_environments
  stage_response_filter Development
  stage_sandbox_channel
  stage_enhanced_security_off
  stage_service_token
else
  TOTAL_STAGES=6
  banner "Knock setup · Production"
  stage_postmark_stream
  stage_postmark_channel
  stage_response_filter Production
  stage_enhanced_security_on
  stage_read_only
  stage_service_token
fi

finish
summary
}

run_wizard "$@"; exit
